 while(queue.length){const id=queue.shift();if(seen.has(id))continue;seen.add(id);for(const dir of ['upstream','downstream']){if(!supports(dir)||!shouldExpand(id,dir))continue;dependenciesFor(id,dir).forEach(d=>{const other=dir==='upstream'?d.upstream_object_id:d.downstream_object_id;visible.add(other);edges.push(edge(d));if(!seen.has(other))queue.push(other)})}}
