 const aliasSources=new Map();S.meta.relations.forEach(relation=>{if(!relevant.has(relation.object_id)||!relation.alias)return;aliasSources.set(`${relation.object_id}\u0000${relation.scope_id}\u0000${relation.alias}`,relation.source_object_id)});S.meta.joins.forEach(join=>{if(!relevant.has(join.object_id))return;parsedFields(join.join_fields).forEach(reference=>{const match=String(reference).match(/^"?([^".]+)"?\."?([^".]+)"?$/);if(!match)return;const sourceObject=aliasSources.get(`${join.object_id}\u0000${join.scope_id}\u0000${match[1]}`);add(sourceObject,match[2])})});return usage;
