 node.children=sources.map(edge=>edge.source_key?{edge,node:buildFieldTree(edge.source_key,nextSeen,counter)}:{edge,node:{kind:'terminal',label:edge.source_object?`${edge.source_object}.${edge.source_column}`:edge.source_column,status:edge.resolution_status,sourceKind:edge.source_kind}});
