function showJunction(targetId,edges){if(S.collapsed.right)setSideCollapsed('right',false);const sourceCount=new Set(edges.map(e=>e.source)).size,terminalMode=edges.every(e=>e.terminal),totalInstances=edges.reduce((sum,e)=>sum+(e.count||1),0);$('#detailEyebrow').textContent=terminalMode?'末端来源汇聚':'上游关系汇聚';$('#detailTitle').textContent=targetId;if(terminalMode){const pathCount=edges.reduce((sum,e)=>sum+(e.data.path_count||0),0),complete=edges.every(e=>e.data.path_complete);$('#detailBody').innerHTML=section('汇聚说明',kv({末端源对象:sourceCount,压缩路径:pathCount,路径状态:complete?'COMPLETE':'UNCONFIRMED',目标对象:targetId}))+edges.map(e=>`<div class="junction-source-group"><strong>${esc(e.source)} <span>${e.data.path_count} 条路径</span></strong>${kv({隐藏中间层数:e.data.hidden_depth,路径状态:e.data.path_complete?'COMPLETE':'UNCONFIRMED'})}</div>`).join('');return}$('#detailBody').innerHTML=section('汇聚说明',kv({上游对象:sourceCount,真实关系实例:totalInstances,目标对象:targetId}))+edges.map(e=>{const relations=e.relations?.length?e.relations:[e.data];return`<div class="junction-source-group"><strong>${esc(e.source)} <span>${relations.length} 个关系实例</span></strong>${relations.map(relationCard).join('')}</div>`}).join('')}
function tooltip(e,event){const j=e.join,tip=$('#edgeTooltip');tip.innerHTML=e.terminal?`<strong>Terminal source · 压缩路径</strong><code>隐藏 ${e.data.hidden_depth} 层中间对象 · ${e.data.path_count} 条上游路径 · ${e.data.path_complete?'COMPLETE':'UNCONFIRMED'}</code>`:e.count>1?`<strong>${e.count} 个关系实例</strong><code>点击查看全部 FROM / JOIN 条件与 SQL 片段</code>`:`<strong>${esc(j?.join_type||e.data.relation_type||'FROM')}</strong><code>${esc(j?.join_condition||j?.sql_fragment||e.data.sql_fragment||'')}</code>`;tip.classList.remove('hidden');moveTip(event)}function moveTip(e){const r=$('#graphViewport').getBoundingClientRect();$('#edgeTooltip').style.left=Math.max(8,e.clientX-r.left+12)+'px';$('#edgeTooltip').style.top=Math.max(8,e.clientY-r.top+12)+'px'}function hideTip(){$('#edgeTooltip').classList.add('hidden')}
