function transform(){$('#graphScene').setAttribute('transform',`translate(${S.panX} ${S.panY}) scale(${S.zoom})`);$('#zoomValue').textContent=Math.round(S.zoom*100)+'%'}function setZoom(z){S.zoom=Math.max(.2,Math.min(2,z));transform()}function fit(){if(!S.graph?.nodes.length)return;const minX=Math.min(...S.graph.nodes.map(n=>n.x)),minY=Math.min(...S.graph.nodes.map(n=>n.y)),maxX=Math.max(...S.graph.nodes.map(n=>n.x))+NODE_W,maxY=Math.max(...S.graph.nodes.map(n=>n.y))+(S.mode==='er'?ER_NODE_H:NODE_H),r=$('#graphViewport').getBoundingClientRect(),pad=34,width=Math.max(1,maxX-minX),height=Math.max(1,maxY-minY);S.zoom=Math.max(.2,Math.min(.95,(r.width-pad*2)/width,(r.height-pad*2)/height));S.panX=(r.width-width*S.zoom)/2-minX*S.zoom;S.panY=(r.height-height*S.zoom)/2-minY*S.zoom;transform()}function fullscreen(){const v=$('#graphViewport');document.fullscreenElement?document.exitFullscreen():v.requestFullscreen?.().then(()=>setTimeout(fit,80))}
