function erSearchList(q,boxId){const box=$('#'+boxId),needle=q.trim().toLowerCase(),rows=(S.erModel?.entities||[]).filter(item=>needle&&item.entity_id.toLowerCase().includes(needle)).slice(0,16);if(!needle){box.classList.add('hidden');return}box.innerHTML=rows.map(item=>`<div class="search-item" data-er-id="${esc(item.entity_id)}"><span>${esc(item.label)}</span><small>${esc(item.entity_type==='VIEW'||item.entity_type==='MATERIALIZED_VIEW'?'派生实体 · '+item.entity_type:item.entity_type)}</small></div>`).join('')||'<div class="search-item">没有匹配实体</div>';box.classList.remove('hidden');box.querySelectorAll('[data-er-id]').forEach(item=>item.onclick=()=>selectErEntity(item.dataset.erId))}
