function erLabelLines(value){const text=String(value||'UNKNOWN'),max=28;if(text.length<=max)return[text];const cut=Math.max(12,text.lastIndexOf('_',max),text.lastIndexOf('.',max));return[text.slice(0,cut+1),text.slice(cut+1,max+cut+1)+(text.length>max+cut+1?'…':'')]}
