 const positioned=[],isolated=entities.filter(item=>!adj.get(item.entity_id).size),offset={y:42};components.forEach(component=>{const root=[...component].sort((a,b)=>adj.get(b).size-adj.get(a).size||a.localeCompare(b))[0],level=new Map([[root,0]]),queue=[root];while(queue.length){const id=queue.shift();adj.get(id).forEach(next=>{if(!level.has(next)){level.set(next,level.get(id)+1);queue.push(next)}})}const buckets=new Map();component.forEach(id=>push(buckets,level.get(id),id));const widest=Math.max(...[...buckets.values()].map(items=>items.length));[...buckets.entries()].sort((a,b)=>a[0]-b[0]).forEach(([depth,items])=>items.sort((a,b)=>adj.get(b).size-adj.get(a).size||a.localeCompare(b)).forEach((id,index)=>positioned.push({...byId.get(id),x:42+depth*300,y:offset.y+index*160})));offset.y+=Math.max(1,widest)*160+110});
