 const noInternalRelations=!S.erSelected&&Boolean(S.erDomain)&&!S.erIncludeContext&&!allRelations.length,domainNotice=$('#erDomainNotice');
 domainNotice.textContent=noInternalRelations?'当前筛选只保留域内关系；在现有 SQL 证据中，该业务域未观察到域内逻辑关联。打开“显示跨域关联”，可查看它与订单、产品主数据或外部来源的连接。':'';
 domainNotice.classList.toggle('hidden',!noInternalRelations);
 const biContext=S.erSelected?S.biErIndex?.byBi?.get(S.erSelected):null;
 const biContextRelations=(biContext?.relationship_ids||[]).map(id=>E.relationships.find(item=>item.relationship_id===id)).filter(Boolean);
 const directRelations=S.erSelected?[...(new Map([...(E.byEntity.get(S.erSelected)||[]),...(E.byEvidenceObject.get(S.erSelected)||[]),...biContextRelations].map(item=>[item.relationship_id,item]))).values()]:allRelations;
 // Selecting a view shows the table-to-table relationships evidenced by that
 // view. The view is a context card, never a fake relationship node.
 const sourceEntityIds=S.erSelected?new Set([...(biContext?.source_entity_ids||[]),...directRelations.flatMap(item=>[item.left_entity_id,item.right_entity_id])].filter(id=>id!==S.erSelected)):new Set();
 const contextualJoins=S.erSelected&&!biContext&&sourceEntityIds.size?E.relationships.filter(item=>item.relationship_type==='LOGICAL_JOIN'&&sourceEntityIds.has(item.left_entity_id)&&sourceEntityIds.has(item.right_entity_id)):[];
 const rawRelations=S.erSelected?[...directRelations,...contextualJoins]:allRelations;
 const relations=erAggregateRelations(rawRelations),linked=new Set(rawRelations.flatMap(item=>[item.left_entity_id,item.right_entity_id]));
