function applyErRelationshipFocus(){
 const focusedIds=S.erFocusedRelationshipIds.size?S.erFocusedRelationshipIds:new Set(S.erFocusedRelationship?[S.erFocusedRelationship]:[]),scene=$('#graphScene');if(!focusedIds.size||!S.erModel){scene.querySelectorAll('.relation-focus,.relation-dim').forEach(element=>element.classList.remove('relation-focus','relation-dim'));return}
 const members=S.erModel.relationships.filter(relation=>focusedIds.has(erPairId(relation)));
 if(!members.length)return;
 const endpoints=new Set(members.flatMap(relation=>[relation.left_entity_id,relation.right_entity_id]));
 scene.querySelectorAll('[data-er-node]').forEach(node=>{const focused=endpoints.has(node.dataset.erNode);node.classList.toggle('relation-focus',focused);node.classList.toggle('relation-dim',!focused)});
 scene.querySelectorAll('.er-edge-group').forEach(edge=>{const focused=focusedIds.has(edge.dataset.erRel);edge.classList.toggle('relation-focus',focused);edge.classList.toggle('relation-dim',!focused)});
}
function focusErRelationship(item,{append=false}={}){if(!item)return;const id=item.relationship_id;if(!append)S.erFocusedRelationshipIds=new Set([id]);else if(S.erFocusedRelationshipIds.has(id))S.erFocusedRelationshipIds.delete(id);else S.erFocusedRelationshipIds.add(id);S.erFocusedRelationship=[...S.erFocusedRelationshipIds].at(-1)||'';applyErRelationshipFocus()}
showErRelationship=function(item,{focus=true,append=false}={}){if(!item)return;if(focus)focusErRelationship(item,{append});const request=++S.erDetailRequest;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(request!==S.erDetailRequest||!S.erFocusedRelationshipIds.has(item.relationship_id))return;showErRelationshipWithUsage(item)}))};
